function journeyColleges(){const filtered=ProductCore.institutions.filter(u=>(productFilters.kind==='All'||u.kind===productFilters.kind)&&(u.name+' '+u.location).toLowerCase().includes(productFilters.query.toLowerCase()));return journeyPage(2,'Find a college to explore.',`<p class="journey-lede">Search by name or place. Compare up to three.</p><form class="college-finder" id="college-search"><div><label for="college-query">College or location</label><input id="college-query" name="query" value="${esc(productFilters.query)}" placeholder="Try Bellevue or Seattle"></div><div><label for="college-kind">Show</label><select id="college-kind" name="kind">${options(['All','University','Community college'],productFilters.kind)}</select></div><button class="btn">Search</button></form><p class="quiet-note" role="status">${filtered.length} colleges · ${(state.collegeCompare||[]).length} selected to compare</p><div class="grid college-choices">${filtered.map(u=>`<article class="college-choice"><span class="eyebrow">${esc(u.location)}</span><h2>${esc(u.name)}</h2><p>${u.kind} · ${u.calendar} calendar</p><label class="college-select"><input type="checkbox" data-compare-college="${esc(u.name)}" ${(state.collegeCompare||[]).includes(u.name)?'checked':''}> Add to comparison</label>${u.kind==='University'?`<button class="btn" data-target-college="${esc(u.name)}">Plan with this college →</button>`:`<button class="btn" data-associate-college="${esc(u.name)}">Plan an associate degree →</button>`}<details><summary>Programs & planning coverage</summary><p>${esc(u.coverage)}</p><p>Confirm your major, costs and entry requirements with the college.</p><a class="journey-secondary" target="_blank" rel="noopener" href="${u.programs}">Official programs ↗</a><br><a class="journey-secondary" target="_blank" rel="noopener" href="${u.admissions}">Official admissions ↗</a></details></article>`).join('')||'<p class="empty">No matches yet. Try a shorter name or a nearby city.</p>'}</div>${collegeComparison()}<details class="journey-footnote"><summary>What Camino can verify</summary>${productCoverage()}</details>`,'explore')}
